<script setup lang="ts">
import {ref,computed,watch,onUnmounted} from 'vue'
import {ApiError} from '../../../api/auth'
import * as api from '../../../api/adminMarketRefresh'
import {savePending,loadPending,clearPending,clearOwner,type PendingCommand} from './marketRefreshPending'
import {label,time} from './marketDataPresentation'
import MarketRefreshHistory from './MarketRefreshHistory.vue'
const props=defineProps<{instrumentId:string;actorUserId:string}>()
const emit=defineEmits<{submitted:[receipt:api.RefreshReceipt];accessDenied:[error:unknown]}>()
const revoked=ref(false),open=ref(false),busy=ref(false),error=ref(''),storageError=ref(false),resendAllowed=ref(false),options=ref<api.RefreshOptions|null>(null),target=ref(''),reason=ref<api.RefreshCommand['reasonCode']>('RECHECK_DATA'),pending=ref<PendingCommand|null>(null),receipt=ref<api.RefreshReceipt|null>(null),view=ref<api.RefreshOperation|null>(null),historyEpoch=ref(0)
let epoch=0,alive=true
const explanations:Record<string,string>={REFRESH_ACTIONS_DISABLED:'行情重取入口尚未开启。可查看预检条件和历史操作。',REFRESH_WORKER_DISABLED:'更新执行器尚未开启，暂不能提交。',REFRESH_CONTEXT_CHANGED:'当前基准已变化或没有可用的 Baostock 未复权版本，请重新预检。',REFRESH_RANGE_UNSUPPORTED:'现有数据范围不支持本次重取。',REFRESH_COOLDOWN:'距离上次登记不足冷却时间，请稍后重新预检。',ACTIVE_REFRESH_EXISTS:'这只股票已有不同范围的更新任务，请先查看原任务。'}
const canSubmit=computed(()=>!revoked.value&&!busy.value&&!pending.value&&!storageError.value&&options.value?.allowed&&options.value.actionsEnabled&&api.validDate(target.value)&&target.value>=options.value.minTargetDate!&&target.value<=options.value.maxTargetDate!)
const current=(e:number)=>alive&&e===epoch
function message(err:unknown){return (err as Error)?.message||'操作结果尚未确认，请查询原操作编号'}
function deny(err:unknown){if(!(err instanceof ApiError)||!(err.status===401||err.status===403&&err.code==='ACCESS_DENIED'))return false;epoch++;revoked.value=true;open.value=false;busy.value=false;options.value=null;pending.value=null;receipt.value=null;view.value=null;resendAllowed.value=false;clearOwner(props.actorUserId);error.value='管理员访问已失效，请重新确认账号。';emit('accessDenied',err);return true}
async function precheck(){if(busy.value||revoked.value)return;open.value=true;const e=epoch,stock=props.instrumentId;busy.value=true;error.value='';try{const v=await api.getRefreshOptions(stock);if(current(e)){options.value=v;target.value=v.defaultTargetDate||''}}catch(err){if(current(e)){if(deny(err))return;error.value=message(err);options.value=null}}finally{if(current(e))busy.value=false}}
function accepted(saved:api.RefreshReceipt,owner:string,stock:string){if(saved.actorUserId!==owner||saved.instrumentId!==stock)throw new Error('原操作归属无法确认');receipt.value=saved;pending.value=null;resendAllowed.value=false;clearPending(owner,stock);historyEpoch.value++;emit('submitted',saved)}
async function send(command:api.RefreshCommand){if(busy.value)return;const e=epoch,owner=props.actorUserId,stock=props.instrumentId;busy.value=true;error.value='';resendAllowed.value=false;try{const v=await api.submitRefresh(stock,command);if(current(e))accepted(v,owner,stock)}catch(err){if(!current(e))return;if(deny(err))return;if(err instanceof ApiError&&err.status===409&&err.data){try{accepted(err.data as api.RefreshReceipt,owner,stock)}catch(invalid){error.value=message(invalid)}}else error.value=message(err)}finally{if(current(e))busy.value=false}}
function submit(){if(!canSubmit.value||!options.value?.baseVersionId||!options.value.headRevision)return;const c:api.RefreshCommand={operationId:crypto.randomUUID(),baseVersionId:options.value.baseVersionId,expectedHeadRevision:options.value.headRevision,targetDate:target.value,reasonCode:reason.value};try{const marker={instrumentId:props.instrumentId,command:c};savePending(props.actorUserId,marker);pending.value=marker;view.value=null;receipt.value=null;void send(c)}catch(err){error.value=message(err);storageError.value=true}}
async function recover(){const marker=pending.value,existing=receipt.value;if(busy.value||!marker&&!existing)return;const e=epoch,owner=props.actorUserId,stock=props.instrumentId,id=marker?.command.operationId||existing!.operationId;busy.value=true;error.value='';resendAllowed.value=false;try{const v=await api.getRefreshOperation(id);if(current(e)){accepted(v.receipt,owner,stock);view.value=v}}catch(err){if(current(e)){if(deny(err))return;error.value=message(err);resendAllowed.value=!!marker&&err instanceof ApiError&&err.status===404&&err.code==='OPERATION_NOT_FOUND'}}finally{if(current(e))busy.value=false}}
watch(()=>[props.actorUserId,props.instrumentId],()=>{epoch++;revoked.value=false;open.value=false;busy.value=false;error.value='';storageError.value=false;resendAllowed.value=false;options.value=null;target.value='';receipt.value=null;view.value=null;pending.value=null;try{pending.value=loadPending(props.actorUserId,props.instrumentId);if(pending.value){open.value=true;void recover()}}catch(err){error.value=message(err);storageError.value=true}},{immediate:true})
onUnmounted(()=>{alive=false;epoch++})
</script>
<template><section class="md-card md-refresh" aria-label="管理员行情重取"><h2>行情更新操作 · {{instrumentId}}</h2><p>重新获取当前 Baostock 未复权（RAW）行情。操作依据当前头，所选历史版本仅用于查看。</p><div class="md-actions"><button type="button" data-test="open-refresh" :aria-expanded="open" :disabled="busy||revoked" @click="precheck">{{options?'刷新重取预检':'重新获取行情'}}</button></div><p v-if="busy" role="status">正在处理，请勿重复提交…</p><p v-if="error" role="alert">{{error}}</p><div v-if="open"><template v-if="options"><p class="md-muted">预检时间：{{time(options.queriedAt)}}。北京时间 20:00 前最多取至昨日，之后最多取至今日；最终范围以本次预检为准。</p><dl><dt>来源与价格口径</dt><dd>{{options.provider||'暂无'}} · {{label(options.priceBasis)}}</dd><dt>现有覆盖</dt><dd>{{options.coverageStart||'暂无'}} ～ {{options.coverageEnd||'暂无'}}</dd><dt>基准版本与修订</dt><dd>{{options.baseVersionId||'暂无'}} · {{options.headRevision||'暂无'}}</dd></dl><p v-if="!options.allowed" role="status">{{explanations[options.reasonCode||'']||'当前条件不支持重取，请核对数据和原任务。'}}</p><p v-if="options.cooldownUntil">最早可再次预检时间：{{time(options.cooldownUntil)}}</p><p v-if="options.activeTaskId">已有任务：<RouterLink :to="{path:'/admin/tasks',query:{taskId:options.activeTaskId}}">查看任务</RouterLink>；相同范围可关联原任务。</p><div class="md-form"><label>目标日期<input v-model="target" type="date" :min="options.minTargetDate||undefined" :max="options.maxTargetDate||undefined" :disabled="busy||!!pending||!options.allowed"></label><label>重取原因<select v-model="reason" :disabled="busy||!!pending"><option value="RECHECK_DATA">核对行情数据</option><option value="RECOVER_UPDATE">恢复行情更新</option></select></label><button type="button" data-test="submit-refresh" :disabled="!canSubmit" @click="submit">确认登记重取任务</button></div><p>将从现有覆盖起始日重新核验至目标日，可能访问数据源。登记排队不代表已更新；原版本和旧分析结果保留。</p></template><div v-if="pending" class="md-recovery" role="status"><p>上次提交结果尚未确认。原操作编号：<code>{{pending.command.operationId}}</code></p><button type="button" data-test="recover-refresh" :disabled="busy" @click="recover">查询原操作结果</button><template v-if="resendAllowed"><p>目前未查到记录；如需继续，只能按相同编号及原正文重新提交。</p><button type="button" :disabled="busy" @click="send(pending.command)">按原编号重发</button></template></div><div v-if="receipt" role="status"><h3>原始登记回执：{{label(receipt.outcome)}}</h3><p>操作编号：<code>{{receipt.operationId}}</code><br>登记时间：{{time(receipt.requestedAt)}}<br>{{receipt.resultCode}}</p><p v-if="receipt.outcome==='REJECTED'">{{explanations[receipt.resultCode]||'本次登记已拒绝，请重新预检条件。'}}</p><template v-if="receipt.taskId"><RouterLink :to="{path:'/admin/tasks',query:{taskId:receipt.taskId}}">查看执行任务</RouterLink><p>当前任务状态：{{view?.task?label(view.task.state):'尚未查询'}}。请以执行结果为准。</p></template><button type="button" data-test="recover-refresh" :disabled="busy" @click="recover">刷新原操作状态</button></div></div><MarketRefreshHistory :key="actorUserId+':'+instrumentId" :instrument-id="instrumentId" :refresh-epoch="historyEpoch" @access-denied="deny"/></section></template>
<style scoped>.md-refresh{overflow-wrap:anywhere}.md-recovery{border-left:3px solid var(--accent);padding:12px 16px;margin:16px 0;background:var(--canvas)}code{font-size:.9em;overflow-wrap:anywhere}button:focus-visible,a:focus-visible{outline:3px solid var(--accent);outline-offset:3px}</style>
